enum NativeTextDecorationDeclaration {
    Value(TextDecorationValue),
    CustomProperty(u64),
    CustomPropertyFallback(u64, TextDecorationValue),
    Inherit,
    Initial,
    Unset,
    Revert,
    RevertLayer,
}

