fn parse_flex_shorthand(value: &str) -> Option<(u32, u32, FlexBasisValue)> {
    let values = value.split_ascii_whitespace().collect::<Vec<_>>();
    match values.as_slice() {
        [value] if value.eq_ignore_ascii_case("none") => Some((0, 0, FlexBasisValue::Auto)),
        [value] if value.eq_ignore_ascii_case("auto") => Some((1, 1, FlexBasisValue::Auto)),
        [grow] => Some((parse_flex_grow(grow)?, 1, FlexBasisValue::Length(0))),
        [grow, second] => {
            let grow = parse_flex_grow(grow)?;
            if let Some(shrink) = parse_flex_shrink(second) {
                Some((grow, shrink, FlexBasisValue::Length(0)))
            } else {
                Some((grow, 1, parse_flex_basis(second)?))
            }
        }
        [grow, shrink, basis] => Some((
            parse_flex_grow(grow)?,
            parse_flex_shrink(shrink)?,
            parse_flex_basis(basis)?,
        )),
        _ => None,
    }
}

fn parse_flex_shorthand_custom_property(
    value: &str,
) -> Option<(
    FlexGrowDeclaration,
    FlexShrinkDeclaration,
    FlexBasisDeclaration,
)> {
    let (name_hash, fallback) = parse_flex_var_arguments(value)?;
    match fallback {
        Some(fallback) => {
            let (grow, shrink, basis) = parse_flex_shorthand(fallback)?;
            Some((
                FlexGrowDeclaration::CustomPropertyShorthandFallback(name_hash, grow),
                FlexShrinkDeclaration::CustomPropertyShorthandFallback(name_hash, shrink),
                FlexBasisDeclaration::CustomPropertyShorthandFallback(name_hash, basis),
            ))
        }
        None => Some((
            FlexGrowDeclaration::CustomPropertyShorthand(name_hash),
            FlexShrinkDeclaration::CustomPropertyShorthand(name_hash),
            FlexBasisDeclaration::CustomPropertyShorthand(name_hash),
        )),
    }
}

fn parse_flex_shorthand_declaration(
    value: &str,
) -> Option<(
    FlexGrowDeclaration,
    FlexShrinkDeclaration,
    FlexBasisDeclaration,
)> {
    if value.trim().eq_ignore_ascii_case("revert-layer") {
        return Some((
            FlexGrowDeclaration::RevertLayer,
            FlexShrinkDeclaration::RevertLayer,
            FlexBasisDeclaration::RevertLayer,
        ));
    }
    if is_local_reset_keyword(value) {
        return Some((
            FlexGrowDeclaration::Reset,
            FlexShrinkDeclaration::Reset,
            FlexBasisDeclaration::Reset,
        ));
    }
    if value.trim().eq_ignore_ascii_case("inherit") {
        return Some((
            FlexGrowDeclaration::Inherit,
            FlexShrinkDeclaration::Inherit,
            FlexBasisDeclaration::Inherit,
        ));
    }
    parse_flex_shorthand(value)
        .map(|(grow, shrink, basis)| {
            (
                FlexGrowDeclaration::Value(grow),
                FlexShrinkDeclaration::Value(shrink),
                FlexBasisDeclaration::Value(basis),
            )
        })
        .or_else(|| parse_flex_shorthand_custom_property(value))
}

fn parse_text_decoration(value: &str) -> Option<TextDecorationValue> {
    let mut bits = 0;
    let mut token_count = 0;
    let mut saw_none = false;

    for token in value.split_ascii_whitespace() {
        token_count += 1;
        if token.eq_ignore_ascii_case("none") {
            if token_count != 1 {
                return None;
            }
            saw_none = true;
            continue;
        }
        if saw_none {
            return None;
        }
        let bit = if token.eq_ignore_ascii_case("underline") {
            TextDecorationValue::UNDERLINE
        } else if token.eq_ignore_ascii_case("overline") {
            TextDecorationValue::OVERLINE
        } else if token.eq_ignore_ascii_case("line-through") {
            TextDecorationValue::LINE_THROUGH
        } else {
            return None;
        };
        if bits & bit != 0 {
            return None;
        }
        bits |= bit;
    }

    if token_count == 0 {
        None
    } else if saw_none {
        Some(TextDecorationValue::none())
    } else {
        Some(TextDecorationValue::new(
            bits & TextDecorationValue::UNDERLINE != 0,
            bits & TextDecorationValue::OVERLINE != 0,
            bits & TextDecorationValue::LINE_THROUGH != 0,
        ))
    }
}

fn parse_text_decoration_declaration(value: &str) -> Option<NativeTextDecorationDeclaration> {
    if let Some((name_hash, fallback)) = parse_flex_var_arguments(value) {
        return match fallback {
            Some(fallback) => parse_text_decoration(fallback).map(|fallback| {
                NativeTextDecorationDeclaration::CustomPropertyFallback(name_hash, fallback)
            }),
            None => Some(NativeTextDecorationDeclaration::CustomProperty(name_hash)),
        };
    }
    match value.trim().to_ascii_lowercase().as_str() {
        "inherit" => Some(NativeTextDecorationDeclaration::Inherit),
        "initial" => Some(NativeTextDecorationDeclaration::Initial),
        "unset" => Some(NativeTextDecorationDeclaration::Unset),
        "revert" => Some(NativeTextDecorationDeclaration::Revert),
        "revert-layer" => Some(NativeTextDecorationDeclaration::RevertLayer),
        _ => parse_text_decoration(value).map(NativeTextDecorationDeclaration::Value),
    }
}

fn parse_text_transform(value: &str) -> Option<TextTransformValue> {
    match value.to_ascii_lowercase().as_str() {
        "none" => Some(TextTransformValue::None),
        "uppercase" => Some(TextTransformValue::Uppercase),
        "lowercase" => Some(TextTransformValue::Lowercase),
        _ => None,
    }
}

pub(crate) fn parse_font_weight(value: &str) -> Option<FontWeightValue> {
    let value = value.trim();
    match value.to_ascii_lowercase().as_str() {
        "normal" | "400" => Some(FontWeightValue::Normal),
        "bold" | "700" => Some(FontWeightValue::Bold),
        _ => value
            .parse::<u16>()
            .ok()
            .and_then(FontWeightValue::from_numeric),
    }
}

pub(crate) fn parse_font_weight_range(value: &str) -> Option<NativeFontWeightRange> {
    let mut values = value.split_ascii_whitespace();
    let min = parse_font_weight(values.next()?)?.numeric();
    let max = match values.next() {
        Some(value) => parse_font_weight(value)?.numeric(),
        None => min,
    };
    if values.next().is_some() || min > max {
        return None;
    }
    Some(NativeFontWeightRange { min, max })
}

fn parse_font_style(value: &str) -> Option<FontStyleValue> {
    match value.trim().to_ascii_lowercase().as_str() {
        "normal" => Some(FontStyleValue::Normal),
        "italic" => Some(FontStyleValue::Italic),
        _ => None,
    }
}
fn parse_font_display(value: &str) -> Option<NativeFontDisplay> {
    NativeFontDisplay::parse(value)
}
pub(crate) fn parse_font_size_adjust(value: &str) -> Option<u16> {
    let percentage = value.trim().strip_suffix('%')?.trim();
    let milli_percentage = parse_decimal_milli(percentage)?;
    let adjusted = milli_percentage.saturating_add(50) / 100;
    let adjusted = u16::try_from(adjusted).ok()?;
    (250..=4000).contains(&adjusted).then_some(adjusted)
}

pub(crate) fn format_font_size_adjust(value: u16) -> String {
    if value % 10 == 0 {
        format!("{}%", value / 10)
    } else {
        format!("{}.{}%", value / 10, value % 10)
    }
}

pub(crate) fn parse_font_metric_override(value: &str) -> Option<Option<u16>> {
    let value = value.trim();
    if value.eq_ignore_ascii_case("normal") {
        return Some(None);
    }
    let percentage = value.strip_suffix('%')?;
    let milli_percentage = parse_decimal_milli(percentage)?;
    let scaled = milli_percentage.saturating_add(50) / 100;
    let scaled = u16::try_from(scaled).ok()?;
    (scaled <= 10_000).then_some(Some(scaled))
}

pub(crate) fn format_font_metric_override(value: Option<u16>) -> String {
    value.map_or_else(|| "normal".into(), format_font_size_adjust)
}

fn parse_font_stretch_token(value: &str) -> Option<u16> {
    let value = value.trim();
    let keyword = match value.to_ascii_lowercase().as_str() {
        "ultra-condensed" => Some(500),
        "extra-condensed" => Some(625),
        "condensed" => Some(750),
        "semi-condensed" => Some(875),
        "normal" => Some(1000),
        "semi-expanded" => Some(1125),
        "expanded" => Some(1250),
        "extra-expanded" => Some(1500),
        "ultra-expanded" => Some(2000),
        _ => None,
    };
    if let Some(keyword) = keyword {
        return Some(keyword);
    }
    let number = value.strip_suffix('%')?;
    let scaled_milli = parse_decimal_milli(number)?;
    let scaled_tenths = scaled_milli.saturating_add(50) / 100;
    let scaled_tenths = u16::try_from(scaled_tenths).ok()?;
    (500..=2000)
        .contains(&scaled_tenths)
        .then_some(scaled_tenths)
}

pub(crate) fn parse_font_stretch_range(value: &str) -> Option<NativeFontStretchRange> {
    let mut values = value.split_ascii_whitespace();
    let min = parse_font_stretch_token(values.next()?)?;
    let max = match values.next() {
        Some(value) => parse_font_stretch_token(value)?,
        None => min,
    };
    if values.next().is_some() || min > max {
        return None;
    }
    Some(NativeFontStretchRange { min, max })
}

/// Parse the single-value `font-stretch` property into percentage tenths.
/// The two-value form is reserved for `@font-face` descriptor ranges.
pub(crate) fn parse_font_stretch_value(value: &str) -> Option<u16> {
    let mut values = value.split_ascii_whitespace();
    let stretch = parse_font_stretch_token(values.next()?)?;
    values.next().is_none().then_some(stretch)
}

pub(crate) fn format_font_stretch_range(range: NativeFontStretchRange) -> String {
    if range.min == range.max {
        let keyword = match range.min {
            500 => Some("ultra-condensed"),
            625 => Some("extra-condensed"),
            750 => Some("condensed"),
            875 => Some("semi-condensed"),
            1000 => Some("normal"),
            1125 => Some("semi-expanded"),
            1250 => Some("expanded"),
            1500 => Some("extra-expanded"),
            2000 => Some("ultra-expanded"),
            _ => None,
        };
        if let Some(keyword) = keyword {
            return keyword.into();
        }
    }
    let format_percentage = |value: u16| {
        if value % 10 == 0 {
            format!("{}%", value / 10)
        } else {
            format!("{}.{}%", value / 10, value % 10)
        }
    };
    if range.min == range.max {
        format_percentage(range.min)
    } else {
        format!(
            "{} {}",
            format_percentage(range.min),
            format_percentage(range.max)
        )
    }
}

pub(crate) fn parse_font_face_unicode_range(value: &str) -> Option<Vec<NativeUnicodeRange>> {
    let mut ranges = Vec::new();
    for token in value.split(',') {
        let token = token.trim();
        if token.is_empty() || token.len() > 16 {
            return None;
        }
        let prefix = token.get(..2)?;
        if !prefix.eq_ignore_ascii_case("u+") {
            return None;
        }
        let value = &token[2..];
        let (start, end) = if let Some((start, end)) = value.split_once('-') {
            if start.is_empty() || end.is_empty() {
                return None;
            }
            (
                u32::from_str_radix(start, 16).ok()?,
                u32::from_str_radix(end, 16).ok()?,
            )
        } else if value.contains('?') {
            let mut saw_question = false;
            let mut start_text = String::with_capacity(value.len());
            let mut end_text = String::with_capacity(value.len());
            for character in value.chars() {
                if character == '?' {
                    saw_question = true;
                    start_text.push('0');
                    end_text.push('F');
                } else {
                    if saw_question || !character.is_ascii_hexdigit() {
                        return None;
                    }
                    start_text.push(character);
                    end_text.push(character);
                }
            }
            if start_text.is_empty() {
                return None;
            }
            (
                u32::from_str_radix(&start_text, 16).ok()?,
                u32::from_str_radix(&end_text, 16).ok()?,
            )
        } else {
            let point = u32::from_str_radix(value, 16).ok()?;
            (point, point)
        };
        if start > end || end > 0x10_FFFF {
            return None;
        }
        ranges.push(NativeUnicodeRange { start, end });
        if ranges.len() > MAX_NATIVE_FONT_FACE_UNICODE_RANGES {
            return None;
        }
    }
    if ranges.is_empty() {
        return None;
    }
    ranges.sort_unstable_by_key(|range| (range.start, range.end));
    let mut merged: Vec<NativeUnicodeRange> = Vec::with_capacity(ranges.len());
    for range in ranges {
        if let Some(previous) = merged.last_mut()
            && range.start <= previous.end.saturating_add(1)
        {
            previous.end = previous.end.max(range.end);
        } else {
            merged.push(range);
        }
    }
    Some(merged)
}

pub(crate) fn format_font_face_unicode_ranges(ranges: &[NativeUnicodeRange]) -> String {
    if ranges.is_empty() {
        return "U+0-10FFFF".into();
    }
    ranges
        .iter()
        .map(|range| {
            if range.start == range.end {
                format!("U+{:X}", range.start)
            } else {
                format!("U+{:X}-{:X}", range.start, range.end)
            }
        })
        .collect::<Vec<_>>()
        .join(", ")
}

fn parse_font_family(value: &str) -> Option<NativeFontFamilyList> {
    NativeFontFamilyList::parse(value)
}

fn parse_font_face_family(value: &str) -> Option<String> {
    let value = value.trim();
    let family = if value.len() >= 2
        && matches!(value.as_bytes().first(), Some(b'"' | b'\''))
        && value.as_bytes().last() == value.as_bytes().first()
    {
        value[1..value.len().saturating_sub(1)].trim()
    } else {
        value
    };
    let families = parse_font_family(value)?;
    let mut parsed = families.iter();
    if !matches!(parsed.next(), Some(NativeFontFamilyValue::Named(_)))
        || parsed.next().is_some()
        || family.is_empty()
        || family.bytes().any(|byte| byte.is_ascii_control())
    {
        return None;
    }
    Some(family.to_owned())
}

fn parse_font_face_src(value: &str) -> Option<Vec<NativeFontFaceSource>> {
    let bytes = value.as_bytes();
    let mut cursor = 0usize;
    let mut sources = Vec::new();
    while cursor < bytes.len() {
        let Some((open, is_url)) = css_function_candidate(bytes, cursor) else {
            let character = value[cursor..]
                .chars()
                .next()
                .expect("CSS source cursor must point at a character");
            cursor = cursor.saturating_add(character.len_utf8());
            continue;
        };
        let close = css_url_function_close(bytes, open.saturating_add(1))?;
        let mut start = open.saturating_add(1);
        while start < close && bytes[start].is_ascii_whitespace() {
            start += 1;
        }
        let mut end = close;
        while end > start && bytes[end - 1].is_ascii_whitespace() {
            end -= 1;
        }
        let token = value.get(start..end)?;
        if is_url {
            let token = if token.len() >= 2
                && matches!(token.as_bytes().first(), Some(b'"' | b'\''))
                && token.as_bytes().last() == token.as_bytes().first()
            {
                &token[1..token.len().saturating_sub(1)]
            } else {
                token
            };
            let token = decode_css_url_value(token)?;
            if is_admissible_font_face_source(&token)
                && !token.bytes().any(|byte| byte.is_ascii_control())
                && token.len() <= MAX_NATIVE_FONT_FACE_SOURCE_BYTES
                && sources.len() < MAX_NATIVE_FONT_FACE_SOURCES
            {
                sources.push(NativeFontFaceSource::Url(token));
            }
        } else if let Some(family) = parse_font_face_local(token)
            && sources.len() < MAX_NATIVE_FONT_FACE_SOURCES
        {
            sources.push(NativeFontFaceSource::Local(family));
        }
        cursor = close.saturating_add(1);
    }
    (!sources.is_empty()).then_some(sources)
}

fn parse_font_face_local(value: &str) -> Option<String> {
    parse_font_face_family(value.trim())
}

fn css_function_candidate(bytes: &[u8], cursor: usize) -> Option<(usize, bool)> {
    if let Some(open) = css_named_function_open(bytes, cursor, b"url") {
        return Some((open, true));
    }
    css_named_function_open(bytes, cursor, b"local").map(|open| (open, false))
}

fn is_admissible_font_face_source(value: &str) -> bool {
    if value.is_empty() || value.starts_with('#') || value.bytes().any(|byte| byte == 0) {
        return false;
    }
    let Ok(url) = url::Url::parse(value) else {
        // Relative URLs and protocol-relative URLs are resolved by the
        // document's resource owner after stylesheet URL canonicalization.
        return !value.contains(':');
    };
    matches!(
        url.scheme().to_ascii_lowercase().as_str(),
        "blob" | "data" | "file" | "http" | "https"
    )
}

fn parse_font_family_name(value: &str) -> Option<NativeFontFamilyValue> {
    match value.trim().to_ascii_lowercase().as_str() {
        "sans-serif" | "ui-sans-serif" => Some(NativeFontFamilyValue::Generic(
            NativeGenericFontFamily::SansSerif,
        )),
        "serif" | "ui-serif" => Some(NativeFontFamilyValue::Generic(
            NativeGenericFontFamily::Serif,
        )),
        "monospace" | "ui-monospace" => Some(NativeFontFamilyValue::Generic(
            NativeGenericFontFamily::Monospace,
        )),
        "cursive" => Some(NativeFontFamilyValue::Generic(
            NativeGenericFontFamily::Cursive,
        )),
        "fantasy" => Some(NativeFontFamilyValue::Generic(
            NativeGenericFontFamily::Fantasy,
        )),
        "system-ui" => Some(NativeFontFamilyValue::Generic(
            NativeGenericFontFamily::SystemUi,
        )),
        _ => (!value.trim().is_empty())
            .then_some(NativeFontFamilyValue::Named(font_family_hash(value))),
    }
}

pub(crate) fn font_family_hash(value: &str) -> u64 {
    let mut hash = 1469598103934665603u64;
    for byte in value
        .trim()
        .bytes()
        .filter(|byte| !byte.is_ascii_whitespace())
    {
        hash ^= u64::from(byte.to_ascii_lowercase());
        hash = hash.wrapping_mul(1099511628211);
    }
    hash
}

fn parse_font_size(value: &str) -> Option<u32> {
    let value = value.trim().to_ascii_lowercase();
    if let Some(number) = value.strip_suffix("px") {
        let milli_pixels = u64::from(parse_font_size_decimal_milli(number.trim())?);
        let pixels = milli_pixels.checked_add(500)?.checked_div(1_000)?;
        return u32::try_from(pixels)
            .ok()
            .filter(|value| (1..=256).contains(value));
    }
    let (number, multiplier, denominator) = [
        ("pt", 4_u64, 3_u64),
        ("pc", 16_u64, 1_u64),
        ("in", 96_u64, 1_u64),
        ("cm", 4_800_u64, 127_u64),
        ("mm", 480_u64, 127_u64),
    ]
    .iter()
    .find_map(|(suffix, multiplier, denominator)| {
        value
            .strip_suffix(suffix)
            .map(|number| (number.trim(), *multiplier, *denominator))
    })?;
    let milli_units = u64::from(parse_font_size_decimal_milli(number)?);
    let milli_pixels = milli_units
        .checked_mul(multiplier)?
        .checked_add(denominator / 2)?
        .checked_div(denominator)?;
    let pixels = milli_pixels.checked_add(999)?.checked_div(1_000)?;
    u32::try_from(pixels)
        .ok()
        .filter(|value| (1..=256).contains(value))
}
fn parse_relative_font_size(value: &str) -> Option<NativeFontSizeDeclarationValue> {
    let value = value.trim().to_ascii_lowercase();
    let (number, root_relative, percentage, viewport_unit) =
        if let Some(number) = value.strip_suffix('%') {
            (number.trim(), false, true, None)
        } else if let Some(number) = value.strip_suffix("rem") {
            (number.trim(), true, false, None)
        } else if let Some(number) = value.strip_suffix("vmin") {
            (
                number.trim(),
                false,
                false,
                Some(NativeViewportFontSizeUnit::Min),
            )
        } else if let Some(number) = value.strip_suffix("vmax") {
            (
                number.trim(),
                false,
                false,
                Some(NativeViewportFontSizeUnit::Max),
            )
        } else if let Some(number) = value.strip_suffix("vw") {
            (
                number.trim(),
                false,
                false,
                Some(NativeViewportFontSizeUnit::Width),
            )
        } else if let Some(number) = value.strip_suffix("vh") {
            (
                number.trim(),
                false,
                false,
                Some(NativeViewportFontSizeUnit::Height),
            )
        } else if let Some(number) = value.strip_suffix("em") {
            (number.trim(), false, false, None)
        } else {
            return None;
        };
    let milli = parse_font_size_decimal_milli(number)?;
    let scale_milli = if percentage {
        milli.checked_add(50)?.checked_div(100)?
    } else {
        milli
    };
    if !(1..=super::font::MAX_NATIVE_FONT_SIZE.saturating_mul(1_000)).contains(&scale_milli) {
        return None;
    }
    Some(if let Some(unit) = viewport_unit {
        NativeFontSizeDeclarationValue::Viewport(scale_milli, unit)
    } else if root_relative {
        NativeFontSizeDeclarationValue::RootRelative(scale_milli)
    } else {
        NativeFontSizeDeclarationValue::Relative(scale_milli)
    })
}

const MAX_NATIVE_FONT_SIZE_CALC_TERMS: usize = 16;
const MAX_NATIVE_FONT_SIZE_CALC_PRODUCT_OPERANDS: usize = 8;

fn merge_font_size_calculation(
    total: &mut NativeFontSizeCalculation,
    term: NativeFontSizeCalculation,
    sign: i64,
) -> Option<()> {
    total.absolute_milli = total
        .absolute_milli
        .checked_add(sign.checked_mul(term.absolute_milli)?)?;
    total.parent_scale_milli = total
        .parent_scale_milli
        .checked_add(sign.checked_mul(term.parent_scale_milli)?)?;
    total.root_scale_milli = total
        .root_scale_milli
        .checked_add(sign.checked_mul(term.root_scale_milli)?)?;
    total.viewport_width_scale_milli = total
        .viewport_width_scale_milli
        .checked_add(sign.checked_mul(term.viewport_width_scale_milli)?)?;
    total.viewport_height_scale_milli = total
        .viewport_height_scale_milli
        .checked_add(sign.checked_mul(term.viewport_height_scale_milli)?)?;
    total.viewport_min_scale_milli = total
        .viewport_min_scale_milli
        .checked_add(sign.checked_mul(term.viewport_min_scale_milli)?)?;
    total.viewport_max_scale_milli = total
        .viewport_max_scale_milli
        .checked_add(sign.checked_mul(term.viewport_max_scale_milli)?)?;
    Some(())
}

fn parse_font_size_calculation_term(value: &str) -> Option<NativeFontSizeCalculation> {
    let value = value.trim();
    let mut term = NativeFontSizeCalculation::default();
    if let Some(number) = value.strip_suffix("px") {
        let milli = parse_font_size_decimal_milli(number.trim())?;
        (milli <= super::font::MAX_NATIVE_FONT_SIZE.saturating_mul(1_000)).then_some(())?;
        term.absolute_milli = i64::from(milli);
        return Some(term);
    }
    let (number, multiplier, denominator) = [
        ("pt", 4_u64, 3_u64),
        ("pc", 16_u64, 1_u64),
        ("in", 96_u64, 1_u64),
        ("cm", 4_800_u64, 127_u64),
        ("mm", 480_u64, 127_u64),
    ]
    .iter()
    .find_map(|(suffix, multiplier, denominator)| {
        value
            .strip_suffix(suffix)
            .map(|number| (number.trim(), *multiplier, *denominator))
    })?;
    let milli_units = u64::from(parse_font_size_decimal_milli(number)?);
    let milli_pixels = milli_units
        .checked_mul(multiplier)?
        .checked_add(denominator / 2)?
        .checked_div(denominator)?;
    if milli_pixels > u64::from(super::font::MAX_NATIVE_FONT_SIZE).saturating_mul(1_000) {
        return None;
    }
    term.absolute_milli = i64::try_from(milli_pixels).ok()?;
    Some(term)
}

fn parse_font_size_calculation_relative_term(
    value: &str,
) -> Option<(u32, Option<NativeViewportFontSizeUnit>, bool)> {
    let (number, root_relative, percentage, viewport_unit) =
        if let Some(number) = value.strip_suffix('%') {
            (number.trim(), false, true, None)
        } else if let Some(number) = value.strip_suffix("rem") {
            (number.trim(), true, false, None)
        } else if let Some(number) = value.strip_suffix("vmin") {
            (
                number.trim(),
                false,
                false,
                Some(NativeViewportFontSizeUnit::Min),
            )
        } else if let Some(number) = value.strip_suffix("vmax") {
            (
                number.trim(),
                false,
                false,
                Some(NativeViewportFontSizeUnit::Max),
            )
        } else if let Some(number) = value.strip_suffix("vw") {
            (
                number.trim(),
                false,
                false,
                Some(NativeViewportFontSizeUnit::Width),
            )
        } else if let Some(number) = value.strip_suffix("vh") {
            (
                number.trim(),
                false,
                false,
                Some(NativeViewportFontSizeUnit::Height),
            )
        } else if let Some(number) = value.strip_suffix("em") {
            (number.trim(), false, false, None)
        } else {
            return None;
        };
    let milli = parse_font_size_decimal_milli(number)?;
    let scale_milli = if percentage {
        milli.checked_add(50)?.checked_div(100)?
    } else {
        milli
    };
    (scale_milli <= super::font::MAX_NATIVE_FONT_SIZE.saturating_mul(1_000)).then_some(())?;
    Some((scale_milli, viewport_unit, root_relative))
}

fn parse_font_size_calculation_term_any(value: &str) -> Option<NativeFontSizeCalculation> {
    let value = value.trim().to_ascii_lowercase();
    if value.starts_with("calc(") {
        return parse_font_size_calculation(&value);
    }
    if let Some(term) = parse_font_size_calculation_term(&value) {
        return Some(term);
    }
    let (scale_milli, viewport_unit, root_relative) =
        parse_font_size_calculation_relative_term(&value)?;
    let mut term = NativeFontSizeCalculation::default();
    match viewport_unit {
        Some(NativeViewportFontSizeUnit::Width) => {
            term.viewport_width_scale_milli = i64::from(scale_milli)
        }
        Some(NativeViewportFontSizeUnit::Height) => {
            term.viewport_height_scale_milli = i64::from(scale_milli)
        }
        Some(NativeViewportFontSizeUnit::Min) => {
            term.viewport_min_scale_milli = i64::from(scale_milli);
        }
        Some(NativeViewportFontSizeUnit::Max) => {
            term.viewport_max_scale_milli = i64::from(scale_milli);
        }
        None if root_relative => term.root_scale_milli = i64::from(scale_milli),
        None => term.parent_scale_milli = i64::from(scale_milli),
    }
    Some(term)
}

fn scale_font_size_calculation(
    calculation: NativeFontSizeCalculation,
    factor_milli: u32,
    divide: bool,
) -> Option<NativeFontSizeCalculation> {
    let factor = i64::from(factor_milli);
    if divide && factor == 0 {
        return None;
    }
    let scale = |value: i64| {
        let denominator = if divide { factor } else { 1_000 };
        let product = if divide {
            value.checked_mul(1_000)?
        } else {
            value.checked_mul(factor)?
        };
        if product >= 0 {
            product
                .checked_add(denominator / 2)?
                .checked_div(denominator)
        } else {
            product
                .checked_sub(denominator / 2)?
                .checked_div(denominator)
        }
    };
    Some(NativeFontSizeCalculation {
        absolute_milli: scale(calculation.absolute_milli)?,
        parent_scale_milli: scale(calculation.parent_scale_milli)?,
        root_scale_milli: scale(calculation.root_scale_milli)?,
        viewport_width_scale_milli: scale(calculation.viewport_width_scale_milli)?,
        viewport_height_scale_milli: scale(calculation.viewport_height_scale_milli)?,
        viewport_min_scale_milli: scale(calculation.viewport_min_scale_milli)?,
        viewport_max_scale_milli: scale(calculation.viewport_max_scale_milli)?,
    })
}

fn parse_font_size_calculation_product(value: &str) -> Option<NativeFontSizeCalculation> {
    enum ProductValue {
        Calculation(NativeFontSizeCalculation),
        Unitless(u32),
    }

    fn parse_operand(value: &str) -> Option<ProductValue> {
        parse_font_size_calculation_term_any(value)
            .map(ProductValue::Calculation)
            .or_else(|| {
                parse_font_size_decimal_milli(value)
                    .filter(|factor| {
                        *factor <= super::font::MAX_NATIVE_FONT_SIZE.saturating_mul(1_000)
                    })
                    .map(ProductValue::Unitless)
            })
    }

    fn scale_unitless(lhs: u32, rhs: u32, divide: bool) -> Option<u32> {
        if divide && rhs == 0 {
            return None;
        }
        let denominator = if divide { u64::from(rhs) } else { 1_000 };
        let product = u64::from(lhs).checked_mul(if divide { 1_000 } else { u64::from(rhs) })?;
        let rounded = product
            .checked_add(denominator / 2)?
            .checked_div(denominator)?;
        u32::try_from(rounded).ok()
    }

    fn apply_product(
        left: ProductValue,
        operator: u8,
        right: ProductValue,
    ) -> Option<ProductValue> {
        let divide = operator == b'/';
        match (left, right, divide) {
            (ProductValue::Calculation(calculation), ProductValue::Unitless(factor), divide) => {
                scale_font_size_calculation(calculation, factor, divide)
                    .map(ProductValue::Calculation)
            }
            (ProductValue::Unitless(factor), ProductValue::Calculation(calculation), false) => {
                scale_font_size_calculation(calculation, factor, false)
                    .map(ProductValue::Calculation)
            }
            (ProductValue::Unitless(left), ProductValue::Unitless(right), divide) => {
                scale_unitless(left, right, divide).map(ProductValue::Unitless)
            }
            _ => None,
        }
    }

    let mut current = None;
    let mut operator = None;
    let mut operand_start = 0;
    let mut operand_count = 0_usize;
    let mut depth = 0_usize;
    for (index, byte) in value.bytes().enumerate() {
        match byte {
            b'(' => depth = depth.checked_add(1)?,
            b')' => {
                if depth == 0 {
                    return None;
                }
                depth = depth.saturating_sub(1);
            }
            b'*' | b'/' if depth == 0 => {
                let operand = value.get(operand_start..index)?.trim();
                if operand.is_empty() {
                    return None;
                }
                operand_count = operand_count.saturating_add(1);
                if operand_count > MAX_NATIVE_FONT_SIZE_CALC_PRODUCT_OPERANDS {
                    return None;
                }
                let parsed = parse_operand(operand)?;
                if let Some(left) = current.take() {
                    current = Some(apply_product(left, operator?, parsed)?);
                } else if operator.is_some() {
                    return None;
                } else {
                    current = Some(parsed);
                }
                operator = Some(byte);
                operand_start = index.saturating_add(1);
            }
            _ => {}
        }
    }
    if depth != 0 {
        return None;
    }

    let operand = value.get(operand_start..)?.trim();
    if operand.is_empty() {
        return None;
    }
    operand_count = operand_count.saturating_add(1);
    if operand_count > MAX_NATIVE_FONT_SIZE_CALC_PRODUCT_OPERANDS {
        return None;
    }
    let parsed = parse_operand(operand)?;
    if let Some(left) = current.take() {
        current = Some(apply_product(left, operator?, parsed)?);
    } else if operator.is_some() {
        return None;
    } else {
        current = Some(parsed);
    }

    match current? {
        ProductValue::Calculation(calculation) => Some(calculation),
        ProductValue::Unitless(_) => None,
    }
}

fn parse_font_size_calculation(value: &str) -> Option<NativeFontSizeCalculation> {
    let value = value.trim().to_ascii_lowercase();
    let source = value.strip_prefix("calc(")?.strip_suffix(')')?;
    if source.trim().is_empty() {
        return None;
    }
    let mut total = NativeFontSizeCalculation::default();
    let mut start = 0;
    let mut sign = 1_i64;
    let mut term_count: usize = 0;
    let mut depth = 0_usize;
    for (index, byte) in source.bytes().enumerate() {
        match byte {
            b'(' => depth = depth.checked_add(1)?,
            b')' => {
                if depth == 0 {
                    return None;
                }
                depth = depth.saturating_sub(1);
            }
            b'+' | b'-' if depth == 0 => {
                let term = source.get(start..index)?.trim();
                if term.is_empty() {
                    return None;
                }
                term_count = term_count.saturating_add(1);
                if term_count > MAX_NATIVE_FONT_SIZE_CALC_TERMS {
                    return None;
                }
                merge_font_size_calculation(
                    &mut total,
                    parse_font_size_calculation_product(term)?,
                    sign,
                )?;
                sign = if byte == b'+' { 1 } else { -1 };
                start = index.saturating_add(1);
            }
            _ => {}
        }
    }
    if depth != 0 {
        return None;
    }
    let term = source.get(start..)?.trim();
    if term.is_empty() {
        return None;
    }
    term_count = term_count.saturating_add(1);
    if term_count > MAX_NATIVE_FONT_SIZE_CALC_TERMS {
        return None;
    }
    merge_font_size_calculation(&mut total, parse_font_size_calculation_product(term)?, sign)?;
    Some(total)
}

fn parse_font_size_variable_expression(value: &str) -> Option<NativeFontSizeVariableExpression> {
    let value = value.trim();
    if value.len() < 9
        || !value
            .get(..5)
            .is_some_and(|prefix| prefix.eq_ignore_ascii_case("calc("))
        || !value.ends_with(')')
        || !value.is_ascii()
    {
        return None;
    }
    let bytes = value.as_bytes();
    let mut depth = 0_usize;
    let mut has_variable = false;
    for index in 0..bytes.len() {
        if bytes
            .get(index..index.saturating_add(4))
            .is_some_and(|candidate| candidate.eq_ignore_ascii_case(b"var("))
        {
            has_variable = true;
        }
        match bytes[index] {
            b'(' => depth = depth.checked_add(1)?,
            b')' => {
                depth = depth.checked_sub(1)?;
                if depth == 0 && index.saturating_add(1) != bytes.len() {
                    return None;
                }
            }
            _ => {}
        }
    }
    (depth == 0 && has_variable).then(|| NativeFontSizeVariableExpression::from_text(value))?
}

fn parse_font_size_value_without_custom(value: &str) -> Option<NativeFontSizeDeclarationValue> {
    parse_font_size_variable_expression(value)
        .map(NativeFontSizeDeclarationValue::VariableCalculation)
        .or_else(|| parse_font_size(value).map(NativeFontSizeDeclarationValue::Pixels))
        .or_else(|| parse_relative_font_size(value))
        .or_else(|| {
            parse_font_size_calculation(value).map(NativeFontSizeDeclarationValue::Calculation)
        })
}

fn parse_font_size_value(value: &str) -> Option<NativeFontSizeDeclarationValue> {
    parse_font_size_value_without_custom(value).or_else(|| parse_font_size_custom_property(value))
}

