        assert_eq!(computed("ltr"), [0, 0, 0, 1]);
        assert_eq!(computed("rtl"), [0, 1, 0, 0]);
        assert_eq!(computed("pair"), [1, 0, 2, 0]);
        assert_eq!(computed("rollback"), [5, 0, 5, 0]);
        assert_eq!(computed("normal"), [3, 0, 3, 0]);
        assert_eq!(computed("mixed"), [0, 1, 0, 1]);
